import React, { useEffect, useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { IoCompassOutline, IoMenuOutline, IoCloseOutline } from 'react-icons/io5';

const Navbar = ({ defaultSticky }) => {
  const [isSticky, setIsSticky] = useState(defaultSticky || false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const location = useLocation();

  useEffect(() => {
    if (!defaultSticky) {
      const handleScroll = () => {
        setIsSticky(window.scrollY > 80);
      };
      window.addEventListener("scroll", handleScroll);
      return () => window.removeEventListener("scroll", handleScroll);
    }
  }, [defaultSticky]);

  const navLinks = [
    { name: 'Home', path: '/' },
    { name: 'Gallery', path: '/gallery' },
    { name: 'Explore', path: '/explore' },
    { name: 'Blog', path: '/blog' },
  ];

  return (
    <>
      <nav className={`navbar ${isSticky ? "sticky" : ""} ${mobileMenuOpen ? "drawer-open" : ""}`}>
        <Link to="/" className="navbar-brand">
          <IoCompassOutline />
          <span>Trip Tips</span>
        </Link>

        <div className="navlist">
          <ul>
            {navLinks.map(link => (
              <li key={link.name} className="navitem">
                <Link
                  to={link.path}
                  className={`nav-link ${location.pathname === link.path ? 'active' : ''}`}
                >
                  {link.name}
                </Link>
              </li>
            ))}
          </ul>
        </div>

        <div className="mobile-toggle" onClick={() => setMobileMenuOpen(!mobileMenuOpen)}>
          {mobileMenuOpen ? <IoCloseOutline /> : <IoMenuOutline />}
        </div>
      </nav>

      {/* Mobile Drawer */}
      <div className={`mobile-drawer ${mobileMenuOpen ? "open" : ""}`}>
        <div className="drawer-content">
          <ul>
            {navLinks.map(link => (
              <li key={link.name} onClick={() => setMobileMenuOpen(false)}>
                <Link to={link.path} className={location.pathname === link.path ? 'active' : ''}>
                  {link.name}
                </Link>
              </li>
            ))}
          </ul>
        </div>
      </div>

      {mobileMenuOpen && (
        <div className="drawer-overlay" onClick={() => setMobileMenuOpen(false)}></div>
      )}
    </>
  );
};

export default Navbar;
