import React, { useState } from "react";
import ReactQuill from "react-quill";
import "react-quill/dist/quill.snow.css";
import "../Blog.css";
import Navbar from "../components/Navbar";
import { IoCloudUploadOutline, IoPaperPlaneOutline, IoLocationOutline } from 'react-icons/io5';

const Blog = () => {
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [location, setLocation] = useState("");
  const [category, setCategory] = useState("Cities");
  const [image, setImage] = useState(null);
  const [status, setStatus] = useState({ type: '', msg: '' });

  const categories = ["Cities", "Nature", "Culture", "History", "Beaches"];

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      setImage(URL.createObjectURL(file));
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const blogData = {
      id: Date.now(),
      title,
      description: description.replace(/<[^>]*>/g, '').substring(0, 500), // Clean HTML for preview
      location,
      category,
      img: image || "https://images.unsplash.com/photo-1488646953014-85cb44e25828",
      startDate: new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' }),
      readTime: "5 min read",
      rating: 5.0,
      tags: [category, "Guest Post"],
      highlights: ["Vibrant local atmosphere", "Hidden gems discovered", "Memorable experience"]
    };

    try {
      // For a real app, this would be an API call. Here we simulate storage.
      const savedPosts = JSON.parse(localStorage.getItem('guestPosts') || '[]');
      localStorage.setItem('guestPosts', JSON.stringify([blogData, ...savedPosts]));

      setStatus({ type: 'success', msg: 'Your wanderlust has been shared! Post published.' });

      // Reset form
      setTitle("");
      setDescription("");
      setLocation("");
      setImage(null);
    } catch (error) {
      setStatus({ type: 'error', msg: 'Failed to publish post. Please try again.' });
    }
  };

  return (
    <section className="blog-page">
      <Navbar defaultSticky />

      <div className="blog-hero">
        <h1>Share Your Story</h1>
        <p>Inspiration comes from everywhere. Where have you been lately?</p>
      </div>

      <div className="blog-container">
        <form onSubmit={handleSubmit} className="blog-form">
          <div className="form-group">
            <label>Trip Title</label>
            <input
              type="text"
              placeholder="e.g. A Weekend in the Swiss Alps"
              className="blog-input"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              required
            />
          </div>

          <div className="form-row">
            <div className="form-group">
              <label>Location</label>
              <div className="input-with-icon">
                <IoLocationOutline />
                <input
                  type="text"
                  placeholder="City, Country"
                  className="blog-input"
                  value={location}
                  onChange={(e) => setLocation(e.target.value)}
                  required
                />
              </div>
            </div>
            <div className="form-group">
              <label>Category</label>
              <select
                className="blog-input"
                value={category}
                onChange={(e) => setCategory(e.target.value)}
              >
                {categories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
              </select>
            </div>
          </div>

          <div className="form-group">
            <label>Your Experience</label>
            <ReactQuill
              value={description}
              onChange={setDescription}
              className="blog-editor"
              theme="snow"
              placeholder="Tell the world about your adventure..."
            />
          </div>

          <div className="form-group">
            <label>Feature Photo</label>
            <label className="image-upload-zone">
              <input
                type="file"
                accept="image/*"
                onChange={handleImageChange}
                className="hidden-file-input"
              />
              {image ? (
                <img src={image} alt="Preview" className="image-preview" />
              ) : (
                <div className="upload-placeholder">
                  <IoCloudUploadOutline />
                  <span>Click to upload or drag and drop</span>
                  <small>PNG, JPG up to 5MB</small>
                </div>
              )}
            </label>
          </div>

          {status.msg && (
            <div className={`status-toast ${status.type}`}>
              {status.msg}
            </div>
          )}

          <button className="blog-submit-btn">
            <IoPaperPlaneOutline />
            Publish Adventure
          </button>
        </form>
      </div>

      <div className="published-posts-section">
        <div className="section-header">
          <h2>Community Adventures</h2>
          <p>Read the latest stories shared by our global community.</p>
        </div>

        <div className="posts-grid">
          {[...JSON.parse(localStorage.getItem('guestPosts') || '[]')].map(post => (
            <div key={post.id} className="guest-post-card">
              <div className="guest-post-img-wrapper">
                <img src={post.img} alt={post.title} />
                <span className="guest-post-category">{post.category}</span>
              </div>
              <div className="guest-post-content">
                <h3>{post.title}</h3>
                <div className="guest-post-meta">
                  <span><IoLocationOutline /> {post.location}</span>
                  <span>{post.startDate}</span>
                </div>
                <p>{post.description}</p>
              </div>
            </div>
          ))}
          {/* If no guest posts, show a friendly message */}
          {JSON.parse(localStorage.getItem('guestPosts') || '[]').length === 0 && (
            <div className="no-guest-posts">
              <p>No stories shared yet. Be the first to publish your adventure!</p>
            </div>
          )}
        </div>
      </div>
    </section>
  );
};

export default Blog;
